{
  "findings": [
    {
      "check_id": "CKV_GCP_68",
      "title": "Pub/Sub topic lacks encryption with a customer-managed key (CMK)",
      "resource": "google_pubsub_topic.notification_queue",
      "severity": "MEDIUM",
      "explanation": "The Pub/Sub topic does not specify a customer-managed encryption key (CMEK). Without CMEK, Google-managed encryption keys are used, which may not meet compliance or organizational security requirements."
    }
  ],
  "patched_code": "resource \"google_pubsub_topic\" \"notification_queue\" {\n  name = \"insurance-claims-processing-platform-pubsub-notifications\"\n  labels = {\n    environment = \"production\"\n    component   = \"notifications\"\n  }\n\n  kms_key_name = \"projects/my-project/locations/global/keyRings/my-keyring/cryptoKeys/my-key\"\n}",
  "fix_summary": "Added the `kms_key_name` attribute to enforce encryption of the Pub/Sub topic with a customer-managed encryption key (CMEK)."
}
